from fastapi import BackgroundTasks, FastAPI

app = FastAPI()


def send_welcome(email: str):
    print('sending to', email)


@app.post('/signup')
def signup(email: str, background_tasks: BackgroundTasks):
    background_tasks.add_task(send_welcome, email)
    return {'ok': True}

from app.main import send_welcome, signup


class RecordingBackgroundTasks:
    """Stand-in for fastapi.BackgroundTasks that records instead of runs."""

    def __init__(self):
        self.tasks = []

    def add_task(self, func, *args, **kwargs):
        self.tasks.append((func, args, kwargs))


def test_signup():
    tasks = RecordingBackgroundTasks()

    assert signup('a@b.c', tasks) == {'ok': True}

    # The welcome email is queued as a background task rather than sent
    # inline, so the response can go out first.
    assert tasks.tasks == [(send_welcome, ('a@b.c',), {})]

