import os,re
reqs=[l.strip() for l in open('requirements.txt') if l.strip() and not l.startswith('#')]
files=[f for f in os.listdir('wheels') if f.endswith('.whl')]
print('reqs:',len(reqs),'wheels:',len(files))
def norm(n): return re.sub(r'[-_.]+','-',n).lower()
idx={}
for f in files:
    p=f.split('-'); idx.setdefault(norm(p[0]),[]).append(p[1])
for r in reqs:
    m=re.match(r'([A-Za-z0-9._-]+)\s*==\s*(.+)',r); n,v=m.groups()
    got=idx.get(norm(n))
    if not got or v not in got: print('MISSING',n,'=='+v,'have:',got)
"
